(7614034, 1232293, 50695, '<td valign="top">7 from me. A fun way to parallel the cropped head with a "cropped" mannequin, and the reds tie them together as well.</td>', '7 from me. A fun way to parallel the cropped head with a "cropped" mannequin, and the reds tie them together as well.', '2019-02-18 11:40:28.000000', NULL, 0),
(7614035, 1232300, 50695, '<td valign="top">I gave this a 7 and would have bumped higher if I''d come back. I think this is a bold composition that frames the interaction in an interesting way and adds a lot of energy to it.</td>', 'I gave this a 7 and would have bumped higher if I''d come back. I think this is a bold composition that frames the interaction in an interesting way and adds a lot of energy to it.', '2019-02-18 11:45:48.000000', NULL, 0),
